def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    L, R = g[:, :w // 2], g[:, w // 2:]
    if background(L) != background(R):
        halves = [L, R]
    else:
        halves = [g[:h // 2], g[h // 2:]]

    def is_marker_half(p):
        bg = background(p)
        comps = components(p != bg)
        return all(len(c) == 1 for c in comps)

    if is_marker_half(halves[0]) and not is_marker_half(halves[1]):
        mk, sh = halves[0], halves[1]
    else:
        mk, sh = halves[1], halves[0]
    mbg, sbg = background(mk), background(sh)
    out = np.full(mk.shape, mbg, dtype=int)
    emit(out, "Start from the marker half: same size and background, loose dots cleared.")
    dots = {}
    for y, x in zip(*np.nonzero(mk != mbg)):
        dots.setdefault(int(mk[y, x]), []).append((int(y), int(x)))
    dotset = {(c, p) for c, ps in dots.items() for p in ps}
    H, W = out.shape

    def marker_count(comp):
        values = [int(sh[y, x]) for y, x in comp]
        body = max(set(values), key=values.count)
        return sum(c != body for c in values)

    for comp in sorted(components(sh != sbg), key=marker_count, reverse=True):
        cols = [int(sh[y, x]) for y, x in comp]
        body = max(set(cols), key=cols.count)
        markers = [(y, x, int(sh[y, x])) for y, x in comp if sh[y, x] != body]
        if not markers:
            continue
        y0, x0, c0 = markers[0]
        for (dy, dx) in dots.get(c0, []):
            oy, ox = dy - y0, dx - x0
            if all((c, (y + oy, x + ox)) in dotset for y, x, c in markers):
                for y, x in comp:
                    ny, nx = y + oy, x + ox
                    if 0 <= ny < H and 0 <= nx < W:
                        out[ny, nx] = sh[y, x]
                dotset -= {(c, (y + oy, x + ox)) for y, x, c in markers}
                emit(out, f"Moved the colour-{body} shape so its markers sit on the matching dots.")
                break
    emit(out, "Final canvas.")
    return out
